  const grid = document.getElementById("technology-grid");
  if (!grid) return;
  const existing = new Set([...grid.querySelectorAll("button[data-tech]")].map(button => button.dataset.tech));
  const fragment = document.createDocumentFragment();
  let index = 119;
  for (const [id, localized] of Object.entries(items)) {
    if (existing.has(id)) continue;
    const card = document.createElement("article");
    card.className = "technology-card";
    card.dataset.expandedResearch = "true";
    const number = document.createElement("span"); number.className = "technology-number"; number.textContent = String(index++).padStart(3, "0");
    const heading = document.createElement("h3"); heading.textContent = localized.en[0];
    const description = document.createElement("p"); description.textContent = localized.en[1];
    const button = document.createElement("button"); button.type = "button"; button.dataset.tech = id; button.textContent = "Explore & contribute";
    card.append(number, heading, description, button); fragment.append(card);
    window.SSSWET_TECHNOLOGIES = window.SSSWET_TECHNOLOGIES || {}; window.SSSWET_TECHNOLOGIES[id] = localized;
  }
  grid.append(fragment); window.SSSWET_EXPANDED_TECHNOLOGY_COUNT = Object.keys(items).length;
